1	// src/lib/rechner/grossspeicher.js
2	//
3	// Renditerechnung eines Batteriegroßspeichers (BESS) – Co-Location am
4	// Solarpark oder Stand-alone am Netzknoten. Reine Funktionen ohne React:
5	//
6	//   node src/lib/rechner/grossspeicher.js      → Selbsttest
7	//
8	// Methodik (offen gelegt, vor Steuern, ohne Finanzierung):
9	//  - Investition: Speichersystem (€/kWh) + Netzanschluss (€/kW) + Baukostenzuschuss
10	//    (nur Stand-alone; netzdienliche Fahrweise mit Abschlag).
11	//  - Erlöse je MW für ein 2-h-System, aufgeteilt in Arbitrage (Day-Ahead/Intraday),
12	//    aFRR und FCR; skaliert mit der Speicherdauer. Co-Location mit Abschlag wegen
13	//    geteilter Anschlussleistung. Arbitrage sinkt mit der Kapazität (Degradation),
14	//    Regelleistung hängt an der Leistung und sinkt nur halb so stark. Dazu ein
15	//    allgemeiner Erlöstrend (mehr Speicher im Markt).
16	//  - Kosten: Betrieb in % der Investition (mit Inflation), Vermarktungsentgelt in %
17	//    der Erlöse, ggf. Netzentgelte auf Ladestrom.
18	//  - Kein Restwert, keine Erweiterung (Augmentation), kein Rückbau.
19	
20	import { SPEICHER, FREIFLAECHE, npv, irr } from "../invest/markt.js";
21	
22	export const STANDORTE = [
23	  { id: "colocation", label: "Co-Location", sub: "am Solarpark" },
24	  { id: "standalone", label: "Stand-alone", sub: "eigener Anschluss" },
25	];
26	
27	export const EBENEN = [
28	  { id: "ms", label: "Mittelspannung", sub: "bis ~ 20 MW" },
29	  { id: "hs", label: "Hochspannung", sub: "110 kV" },
30	];
31	
32	export const DAUERN = [1, 2, 3, 4];
33	
34	const mittel = SPEICHER.erloesProMwJahr.mittel;
35	export const ERLOESNIVEAUS = [
36	  { id: "vorsichtig", label: "Vorsichtig", sub: "Floor/Tolling-Niveau", proMw: SPEICHER.erloesProMwJahr.min },
37	  { id: "mittel", label: "Mittel", sub: "Merchant, realistisch", proMw: mittel },
38	  { id: "optimistisch", label: "Optimistisch", sub: "gute Vermarktung", proMw: SPEICHER.erloesProMwJahr.max },
39	];
40	
41	export const erloesAufteilung = (proMw) => ({
42	  arbitrage: Math.round((proMw * SPEICHER.erloesMix.arbitrage) / 1000) * 1000,
43	  afrr: Math.round((proMw * SPEICHER.erloesMix.afrr) / 1000) * 1000,
44	  fcr: Math.round((proMw * SPEICHER.erloesMix.fcr) / 1000) * 1000,
45	});
46	
47	export const STANDARD = {
48	  mw: 10,
49	  dauer: 2,
50	  capexKwh: SPEICHER.capexProKwh.mittel,
51	  standort: "standalone",
52	  ebene: "ms",
53	  netzdienlich: false,
54	  erloese: erloesAufteilung(mittel),
55	  netzentgeltBefreit: true,
56	  lebensdauer: SPEICHER.lebensdauer,
57	  degradation: SPEICHER.degradation,
58	  erloesTrend: SPEICHER.erloesTrend,
59	  zyklen: SPEICHER.zyklenProJahr,
60	  diskont: SPEICHER.diskont,
61	};
62	
63	export function investitionSpeicher(e) {
64	  const kw = e.mw * 1000;
65	  const kwh = kw * e.dauer;
66	  const system = kwh * e.capexKwh;
67	  const co = e.standort === "colocation";
68	  const netz = kw * (co ? SPEICHER.netzanschlussProKw.coLocation : SPEICHER.netzanschlussProKw[e.ebene]);
69	  const bkz = co ? 0 : kw * SPEICHER.bkzProKw[e.ebene] * (e.netzdienlich ? SPEICHER.bkzNetzdienlichFaktor : 1);
70	  return { system, netz, bkz, summe: system + netz + bkz, kwh };
71	}
72	
73	export function rechneSpeicher(eingabe = {}) {
74	  const e = { ...STANDARD, ...eingabe, erloese: { ...STANDARD.erloese, ...(eingabe.erloese || {}) } };
75	  const inv = investitionSpeicher(e);
76	  const dauerF = SPEICHER.dauerFaktor[e.dauer] ?? 1;
77	  const standortF = e.standort === "colocation" ? SPEICHER.coLocationErloesFaktor : 1;
78	  const basis = e.mw * dauerF * standortF;
79	
80	  const jahre = [];
81	  for (let t = 1; t <= e.lebensdauer; t++) {
82	    const trend = Math.pow(1 + e.erloesTrend, t - 1);
83	    const kap = Math.pow(1 - e.degradation, t - 1);
84	    const leistung = Math.pow(1 - e.degradation / 2, t - 1);
85	    const arbitrage = e.erloese.arbitrage * basis * kap * trend;
86	    const afrr = e.erloese.afrr * basis * leistung * trend;
87	    const fcr = e.erloese.fcr * basis * leistung * trend;
88	    const erloes = arbitrage + afrr + fcr;
89	    const betrieb = inv.system * SPEICHER.opexAnteilCapex * Math.pow(1 + FREIFLAECHE.inflation, t - 1);
90	    const vermarktung = erloes * SPEICHER.vermarktungAnteil;
91	    const entladen = inv.kwh * e.zyklen * kap; // kWh
92	    const geladen = entladen / SPEICHER.wirkungsgrad;
93	    const netzentgelt = e.netzentgeltBefreit ? 0 : geladen * (SPEICHER.netzentgeltCt / 100);
94	    const kosten = betrieb + vermarktung + netzentgelt;
95	    jahre.push({ jahr: t, arbitrage, afrr, fcr, erloes, betrieb, vermarktung, netzentgelt, kosten, cf: erloes - kosten, entladenMwh: entladen / 1000 });
96	  }
97	
98	  const cfs = [-inv.summe, ...jahre.map((j) => j.cf)];
99	  const projektIrr = irr(cfs);
100	  const kapitalwert = npv(e.diskont, cfs);
101	  let kum = -inv.summe;
102	  let amortisation = null;
103	  const kumuliert = [kum];
104	  for (const j of jahre) {
105	    const vorher = kum;
106	    kum += j.cf;
107	    kumuliert.push(kum);
108	    if (amortisation == null && kum >= 0 && j.cf > 0) amortisation = j.jahr - 1 + -vorher / j.cf;
109	  }
110	  const j1 = jahre[0];
111	  return {
112	    eingabe: e,
113	    investition: inv,
114	    investProKwh: inv.summe / inv.kwh,
115	    mwh: inv.kwh / 1000,
116	    jahre,
117	    kumuliert,
118	    erloesJahr1: j1.erloes,
119	    erloesProMwJahr1: j1.erloes / e.mw,
120	    cfJahr1: j1.cf,
121	    projektIrr,
122	    kapitalwert,
123	    amortisation,
124	    summeCf: jahre.reduce((s, j) => s + j.cf, 0),
125	    zyklenTag: e.zyklen / 365,
126	  };
127	}
128	
129	/** Co-Location und Stand-alone mit sonst gleichen Eingaben */
130	export function vergleichStandorte(eingabe = {}) {
131	  return STANDORTE.map((s) => ({ ...s, r: rechneSpeicher({ ...eingabe, standort: s.id }) }));
132	}
133	
134	/* ------------------------------------------------------------------ */
135	/* Selbsttest: node src/lib/rechner/grossspeicher.js                   */
136	/* ------------------------------------------------------------------ */
137	
138	export function selbsttest() {
139	  const fehler = [];
140	  const pruefe = (ok, t) => ok || fehler.push(t);
141	
142	  const r = rechneSpeicher({ mw: 10, dauer: 2, capexKwh: 250, standort: "standalone", ebene: "ms", netzdienlich: false });
143	  pruefe(r.mwh === 20, "10 MW × 2 h = 20 MWh");
144	  pruefe(Math.abs(r.investition.system - 5_000_000) < 1, "System 20.000 kWh × 250 € = 5 Mio. €");
145	  pruefe(Math.abs(r.investition.bkz - 10000 * SPEICHER.bkzProKw.ms) < 1, "BKZ = kW × €/kW");
146	  pruefe(Math.abs(r.erloesJahr1 - 10 * (r.eingabe.erloese.arbitrage + r.eingabe.erloese.afrr + r.eingabe.erloese.fcr)) < 1, "Erlös Jahr 1 = MW × Summe Märkte (2 h, Stand-alone)");
147	  pruefe(r.projektIrr > 0.05 && r.projektIrr < 0.3, `IRR plausibel 5–30 % (ist ${(r.projektIrr * 100).toFixed(1)} %)`);
148	  pruefe(r.jahre[14].erloes < r.jahre[0].erloes, "Erlöse sinken über die Laufzeit");
149	
150	  const nd = rechneSpeicher({ mw: 10, dauer: 2, capexKwh: 250, netzdienlich: true });
151	  pruefe(nd.investition.bkz < r.investition.bkz && nd.projektIrr > r.projektIrr, "netzdienlicher BKZ-Abschlag verbessert die Rendite");
152	  const co = rechneSpeicher({ mw: 10, dauer: 2, capexKwh: 250, standort: "colocation" });
153	  pruefe(co.investition.bkz === 0, "Co-Location ohne BKZ");
154	  pruefe(co.erloesJahr1 < r.erloesJahr1, "Co-Location mit Erlösabschlag");
155	  const netz = rechneSpeicher({ mw: 10, dauer: 2, capexKwh: 250, netzentgeltBefreit: false });
156	  pruefe(netz.jahre[0].netzentgelt > 0 && netz.projektIrr < r.projektIrr, "Netzentgelte ohne Befreiung senken die Rendite");
157	  const lang = rechneSpeicher({ mw: 10, dauer: 4, capexKwh: 250 });
158	  pruefe(lang.investition.system === 2 * r.investition.system && lang.erloesJahr1 > r.erloesJahr1, "4 h: doppelte Kapazität, mehr Erlös");
159	  pruefe(Math.abs(r.kumuliert[r.kumuliert.length - 1] - (r.summeCf - r.investition.summe)) < 1, "kumulierter Cashflow konsistent");
160	  pruefe(vergleichStandorte({ mw: 10 }).length === 2, "Vergleich beider Standorte");
161	  return { fehler, beispiel: rechneSpeicher() };
162	}
163	
164	if (typeof process !== "undefined" && process.argv?.[1] && /grossspeicher\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
165	  const { fehler, beispiel: r } = selbsttest();
166	  const p = (x) => (x == null ? "–" : `${(x * 100).toFixed(1)} %`);
167	  console.log(
168	    `Beispiel 10 MW / 20 MWh Stand-alone MS: Invest ${(r.investition.summe / 1e6).toFixed(2)} Mio. €, Erlös J1 ${Math.round(r.erloesJahr1 / 1000)} T€, ` +
169	      `IRR ${p(r.projektIrr)}, NPV ${(r.kapitalwert / 1e6).toFixed(2)} Mio. €, Amortisation ${r.amortisation?.toFixed(1)} J.`
170	  );
171	  const co = rechneSpeicher({ standort: "colocation" });
172	  console.log(`Co-Location: Invest ${(co.investition.summe / 1e6).toFixed(2)} Mio. €, IRR ${p(co.projektIrr)}`);
173	  if (fehler.length) {
174	    console.error("FEHLER:\n- " + fehler.join("\n- "));
175	    process.exit(1);
176	  }
177	  console.log("Selbsttest grossspeicher.js: alle Prüfungen bestanden.");
178	}
