39	const invest = { min: MWH * 1000 * SPEICHER.capexProKwh.min, mittel: MWH * 1000 * SPEICHER.capexProKwh.mittel, max: MWH * 1000 * SPEICHER.capexProKwh.max };
40	const erloes = { min: MW * SPEICHER.erloesProMwJahr.min, mittel: MW * SPEICHER.erloesProMwJahr.mittel, max: MW * SPEICHER.erloesProMwJahr.max };
41	
42	const FAQ = [
43	  {
44	    q: "Co-Location oder Stand-alone – was ist besser?",
45	    a: "Das hängt vom Netzanschluss ab. Co-Location nutzt den Netzanschluss eines Solarparks mit: Der Speicher nimmt Mittagsspitzen auf, die sonst abgeregelt oder billig verkauft würden, und speist abends ein – ohne zusätzliche Anschlussleistung. Stand-alone-Speicher an Umspannwerken sind frei in der Fahrweise und größer skalierbar, brauchen aber einen eigenen, oft knappen Netzanschluss und zahlen in der Regel einen Baukostenzuschuss.",
46	  },
47	  {
48	    q: "Womit verdient ein Großspeicher Geld?",
49	    a: `Mit Preisunterschieden am Strommarkt (Day-Ahead und Intraday), mit Regelenergie (Primärregelleistung FCR und Sekundärregelleistung aFRR) und – am Solarpark – mit verschobenem Solarstrom. Die Erlöse schwanken stark mit dem Markt; wir rechnen vorsichtig mit ${fmt(SPEICHER.erloesProMwJahr.min / 1000)}–${fmt(SPEICHER.erloesProMwJahr.max / 1000)} T€ je MW und Jahr. Indizes zeigen zeitweise höhere theoretische Potenziale, die in der Praxis nur teilweise erreicht werden. Für die Finanzierung werden zunehmend Tolling- oder Floor-Verträge mit Vermarktern genutzt.`,
50	  },
51	  {
52	    q: "Muss ein Speicher einen Baukostenzuschuss zahlen?",
53	    a: "Nach der Entscheidung des Bundesgerichtshofs vom 15. Juli 2025 (EnVR 1/24) dürfen Netzbetreiber auch von Batteriespeichern einen Baukostenzuschuss nach dem Leistungspreismodell verlangen. Je nach Netzebene und Netzgebiet kann das die Investition spürbar erhöhen. Bei Co-Location am bestehenden Anschluss eines Solarparks fällt er für die gemeinsam genutzte Leistung in der Regel nicht erneut an – das ist im Einzelfall mit dem Netzbetreiber zu klären.",
54	  },
55	  {
56	    q: "Zahlt ein Speicher Netzentgelte?",
57	    a: "Nach § 118 Abs. 6 EnWG sind Stromspeicher, die bis zum 4. August 2029 in Betrieb gehen, 20 Jahre lang von Netzentgelten für den eingespeicherten und wieder eingespeisten Strom befreit. Die Bundesnetzagentur arbeitet an einer Reform der Netzentgeltsystematik; nach aktuellem Stand ist für Anlagen innerhalb der Frist Vertrauensschutz zu erwarten – die Entwicklung sollte bei jeder Investitionsentscheidung geprüft werden.",
58	  },
59	  {
60	    q: "Wie sicher sind Großspeicher?",
61	    a: "Heute werden fast ausschließlich Lithium-Eisenphosphat-Zellen (LFP) eingesetzt, die thermisch deutlich stabiler sind als ältere Zellchemien. Dazu kommen Zell- und Modulüberwachung, Gasdetektion, Abstände zwischen Containern, Löschkonzepte mit der Feuerwehr und Prüfungen nach anerkannten Normen. Ein Brandschutzkonzept ist Teil jeder Genehmigung.",
62	  },
63	  {
64	    q: "Gilt das auch in Österreich und der Schweiz?",
65	    a: "Die Erlösquellen sind ähnlich – Regelenergie über APG bzw. Swissgrid, Arbitrage an den Strombörsen. Netzentgelte, Anschlussregeln und Genehmigung unterscheiden sich aber. In Österreich spielen Speicher zudem in Erneuerbare-Energie-Gemeinschaften und bei Photovoltaik-Parks mit begrenzter Einspeiseleistung eine wachsende Rolle. Wir prüfen die Rahmenbedingungen je Standort.",
66	  },
67	];
